-- id=45  سودة بنت زمعة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 45;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سودة بنت زمعة بن قيس بن عبد شمس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي القرشية العامرية وأمها الشموس بنت قيس بن زيد بن عمرو بن لبيد بن خراش بن عامر بن غنم بن عدي بن النجار الأنصارية وسودة هي زوج النبي صلى الله عليه وسلم تزوجها رسول الله صلى الله عليه وسلم بمكة بعد وفاة خديجة قبل عائشة قاله عقيل عن الزهري وقاله قتادة وأبو عبيدة وابن إسحاق وقال عبد الله بن محمد بن عقيل تزوجها بعد عائشة ورواه يونس عن الزهري وكانت قبله تحت ابن عمها السكران بن عمرو أخي سهيل بن عمرو من بني عامر بن لؤي وكان مسلما فتوفي عنها فتزوجها رسول الله صلى الله عليه وسلم وكانت امرأة ثقيلة ثبطة وأسنت عند رسول الله صلى الله عليه وسلم ولم تصب منه ولدا إلى أن مات وروى محمد بن إسحاق عن حكيم بن حكيم عن محمد بن علي بن الحسين عن أبيه قال كان جميع ما تزوج رسول الله صلى الله عليه وسلم خمس عشرة امرأة وكان أول امرأة تزوجها بعد خديجة بنت خويلد سودة بنت زمعة أخبرنا غير واحد بإسنادهم عن محمد بن عيسى قال حدثنا محمد بن المثنى أخبرنا أبو داود الطيالسي أخبرنا سليمان بن معاذ عن سماك عن عكرمة عن ابن عباس قال خشيت سودة أن

يطلقها رسول الله صلى الله عليه وسلم فقالت لا تطلقني وأمسكني واجعل يومي لعائشة ففعل فنزلت فلا جناح عليهما أن يصالحا بينهما صلحا والصلح خير فما اصطلحا عليه من شئ فهو جائز أخبرنا عبد الوهاب بن هبة الله بإسناده عن عبد الله حدثني أبي حدثنا عبد العزيز بن عبد الصمد العمي أبو عبد الصمد حدثنا منصور عن مجاهد مولى لابن الزبير يقال له يوسف بن الزبير أو الزبير بن يوسف عن ابن الزبير عن سودة بنت زمعة قالت جاء رجل إلى رسول الله صلى الله عليه وسلم فقال إن أبي شيخ كبير لا يستطيع أن يحج قال أرأيت لو كان على أبيك دين فقضيته عنه قبل منك قال نعم قال فالله أرحم حج عن أبيك وتوفيت سودة آخر خلافة عمر أخرجها الثلاثة'
WHERE id = 45
  AND content_ar LIKE '(ب د ع) سودة بنت زمع%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 45;
